// Iterative probe shim v2: real implementations of the first-tier vscode API
// surface, so activation can converge empirically.
const path = require("path");
const fs = require("fs");

const EXTENSION_ROOT = process.env.PROBE_EXTENSION_ROOT || process.cwd();

class Disposable {
  constructor(fn) {
    this._fn = fn;
  }
  dispose() {
    if (this._fn) this._fn();
  }
  static from(...items) {
    return new Disposable(() => items.forEach((i) => i.dispose && i.dispose()));
  }
}

class EventEmitter {
  constructor() {
    this._handlers = [];
    this.event = (listener, thisArgs) => {
      this._handlers.push(listener);
      return new Disposable(() => {
        this._handlers = this._handlers.filter((h) => h !== listener);
      });
    };
  }
  fire(data) {
    this._handlers.forEach((h) => h(data));
  }
  dispose() {
    this._handlers = [];
  }
}

function makeUri(input) {
  if (typeof input === "string") {
    return { fsPath: input, path: input, scheme: "file", toString: () => input };
  }
  if (input && typeof input === "object" && input.fsPath) return input;
  return { fsPath: String(input), path: String(input), scheme: "file", toString: () => String(input) };
}

const Uri = {
  file: (p) => makeUri(p),
  parse: (p) => makeUri(p),
  joinPath: (base, ...parts) => makeUri(path.join(base.fsPath, ...parts.map((p) => p.fsPath || p))),
  from: (components) => makeUri(components.path || components.fsPath),
};

