// Minimal l10n: load the bundled l10n bundle for the current language.
const l10nState = { language: "en", bundle: {} };
function loadL10nBundle(language) {
  const candidates = [
    path.join(EXTENSION_ROOT, "l10n", `bundle.l10n.${language}.json`),
    path.join(EXTENSION_ROOT, "l10n", "bundle.l10n.json"),
  ];
  for (const candidate of candidates) {
    try {
      if (fs.existsSync(candidate)) {
        const parsed = JSON.parse(fs.readFileSync(candidate, "utf8"));
        // VS Code bundles nest messages under the extension id sometimes.
        return parsed.contents || parsed;
      }
    } catch {}
  }
  return {};
}
const l10n = {
  t: (message, ...args) => {
    const table = l10nState.bundle || {};
    let template = table[message] || message;
    if (args && args.length) {
      const values = args[0];
      if (typeof values === "object" && values !== null) {
        template = template.replace(/\{(\w+)\}/g, (m, key) =>
          Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : m,
        );
      } else {
        template = template.replace(/\{(\d+)\}/g, (m, idx) => String(args[Number(idx)] ?? m));
      }
    }
    return template;
  },
  bundle: {},
  uri: undefined,
};

const commands = {
  registerCommand: (id, handler) => {
    globalThis.__probeCommands = globalThis.__probeCommands || new Map();
    globalThis.__probeCommands.set(id, handler);
    return new Disposable(() => globalThis.__probeCommands.delete(id));
  },
  registerTextEditorCommand: () => new Disposable(() => {}),
  executeCommand: async (id, ...args) => {
    const handler = (globalThis.__probeCommands || new Map()).get(id);
    if (handler) return handler(...args);
    return undefined;
  },
  getCommands: async () => [...(globalThis.__probeCommands || new Map()).keys()],
};

